import * as React from 'react';

export interface BrandIconProps extends React.SVGProps<SVGSVGElement> {
  name: string;
  size?: number;
}

export function hasBrandIcon(name: string | undefined | null): boolean {
  if (!name) return false;
  return Object.prototype.hasOwnProperty.call(ICONS, name);
}

export function BrandIcon({ name, size = 24, className, ...rest }: BrandIconProps) {
  const ico = (ICONS as Record<string, IconDef>)[name];
  if (!ico) return null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={ico.viewBox}
      width={size}
      height={size}
      className={className}
      dangerouslySetInnerHTML={{ __html: ico.inner }}
      {...rest}
    />
  );
}
